Отброшенный AnyCancellable освобождается и отменяет подписку. Сохрани его в свойстве, чтобы наблюдение пережило вызов start.

import Combine
let selected = CurrentValueSubject<Int, Never>(32)
let subscription = selected
    .map { "Документ \($0)" }
    .sink { print($0) }
selected.send(33)
subscription.cancel()
selected.send(34)

Текущее 32 приходит сразу при подписке, затем приходит 33. После cancel отправка 34 не вызывает sink.

import Combine
struct RevisionEvent { let documentID: Int; let revision: Int }
final class RevisionMonitor {
    private var subscription: AnyCancellable?
    private(set) var revision = 0
    func start(events: PassthroughSubject<RevisionEvent, Never>) {
        subscription = events
            .filter { $0.documentID == 32 }
            .map { $0.revision }
            .sink { [weak self] value in self?.revision = value }
    }
    func stop() { subscription?.cancel(); subscription = nil }
}
let events = PassthroughSubject<RevisionEvent, Never>()
let monitor = RevisionMonitor()
monitor.start(events: events)
events.send(RevisionEvent(documentID: 33, revision: 9))
events.send(RevisionEvent(documentID: 32, revision: 2))
print(monitor.revision)
monitor.stop()
events.send(RevisionEvent(documentID: 32, revision: 3))
print(monitor.revision)

Отфильтрованный чужой документ не влияет на revision. После отмены она остаётся последней полученной: обе строки вывода — 2.
